//! Route to services and handlers based on HTTP methods.

use super::IntoMakeService;
#[cfg(feature = "tokio")]
use crate::extract::connect_info::IntoMakeServiceWithConnectInfo;
use crate::{
    body::{Body, Bytes, HttpBody},
    boxed::BoxedIntoRoute,
    error_handling::{HandleError, HandleErrorLayer},
    handler::Handler,
    http::{Method, Request, StatusCode},
    response::Response,
    routing::{future::RouteFuture, Fallback, MethodFilter, Route},
};
use axum_core::response::IntoResponse;
use bytes::BytesMut;
use std::{
    convert::Infallible,
    fmt,
    task::{Context, Poll},
};
use tower::{service_fn, util::MapResponseLayer};
use tower_layer::Layer;
use tower_service::Service;

macro_rules! top_level_service_fn {
    (
        $name:ident, GET
    ) => {
        top_level_service_fn!(
            /// Route `GET` requests to the given service.
            ///
            /// # Example
            ///
            /// ```rust
            /// use axum::{
            ///     http::Request,
            ///     Router,
            ///     routing::get_service,
            /// };
            /// use http::Response;
            /// use std::convert::Infallible;
            /// use hyper::Body;
            ///
            /// let service = tower::service_fn(|request: Request<Body>| async {
            ///     Ok::<_, Infallible>(Response::new(Body::empty()))
            /// });
            ///
            /// // Requests to `GET /` will go to `service`.
            /// let app = Router::new().route("/", get_service(service));
            /// # async {
            /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
            /// # };
            /// ```
            ///
            /// Note that `get` routes will also be called for `HEAD` requests but will have
            /// the response body removed. Make sure to add explicit `HEAD` routes
            /// afterwards.
            $name,
            GET
        );
    };

    (
        $name:ident, $method:ident
    ) => {
        top_level_service_fn!(
            #[doc = concat!("Route `", stringify!($method) ,"` requests to the given service.")]
            ///
            /// See [`get_service`] for an example.
            $name,
            $method
        );
    };

    (
        $(#[$m:meta])+
        $name:ident, $method:ident
    ) => {
        $(#[$m])+
        pub fn $name<T, S, B>(svc: T) -> MethodRouter<S, B, T::Error>
        where
            T: Service<Request<B>> + Clone + Send + 'static,
            T::Response: IntoResponse + 'static,
            T::Future: Send + 'static,
            B: HttpBody + Send + 'static,
            S: Clone,
        {
            on_service(MethodFilter::$method, svc)
        }
    };
}

macro_rules! top_level_handler_fn {
    (
        $name:ident, GET
    ) => {
        top_level_handler_fn!(
            /// Route `GET` requests to the given handler.
            ///
            /// # Example
            ///
            /// ```rust
            /// use axum::{
            ///     routing::get,
            ///     Router,
            /// };
            ///
            /// async fn handler() {}
            ///
            /// // Requests to `GET /` will go to `handler`.
            /// let app = Router::new().route("/", get(handler));
            /// # async {
            /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
            /// # };
            /// ```
            ///
            /// Note that `get` routes will also be called for `HEAD` requests but will have
            /// the response body removed. Make sure to add explicit `HEAD` routes
            /// afterwards.
            $name,
            GET
        );
    };

    (
        $name:ident, $method:ident
    ) => {
        top_level_handler_fn!(
            #[doc = concat!("Route `", stringify!($method) ,"` requests to the given handler.")]
            ///
            /// See [`get`] for an example.
            $name,
            $method
        );
    };

    (
        $(#[$m:meta])+
        $name:ident, $method:ident
    ) => {
        $(#[$m])+
        pub fn $name<H, T, S, B>(handler: H) -> MethodRouter<S, B, Infallible>
        where
            H: Handler<T, S, B>,
            B: HttpBody + Send + 'static,
            T: 'static,
            S: Clone + Send + Sync + 'static,
        {
            on(MethodFilter::$method, handler)
        }
    };
}

macro_rules! chained_service_fn {
    (
        $name:ident, GET
    ) => {
        chained_service_fn!(
            /// Chain an additional service that will only accept `GET` requests.
            ///
            /// # Example
            ///
            /// ```rust
            /// use axum::{
            ///     http::Request,
            ///     Router,
            ///     routing::post_service,
            /// };
            /// use http::Response;
            /// use std::convert::Infallible;
            /// use hyper::Body;
            ///
            /// let service = tower::service_fn(|request: Request<Body>| async {
            ///     Ok::<_, Infallible>(Response::new(Body::empty()))
            /// });
            ///
            /// let other_service = tower::service_fn(|request: Request<Body>| async {
            ///     Ok::<_, Infallible>(Response::new(Body::empty()))
            /// });
            ///
            /// // Requests to `POST /` will go to `service` and `GET /` will go to
            /// // `other_service`.
            /// let app = Router::new().route("/", post_service(service).get_service(other_service));
            /// # async {
            /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
            /// # };
            /// ```
            ///
            /// Note that `get` routes will also be called for `HEAD` requests but will have
            /// the response body removed. Make sure to add explicit `HEAD` routes
            /// afterwards.
            $name,
            GET
        );
    };

    (
        $name:ident, $method:ident
    ) => {
        chained_service_fn!(
            #[doc = concat!("Chain an additional service that will only accept `", stringify!($method),"` requests.")]
            ///
            /// See [`MethodRouter::get_service`] for an example.
            $name,
            $method
        );
    };

    (
        $(#[$m:meta])+
        $name:ident, $method:ident
    ) => {
        $(#[$m])+
        #[track_caller]
        pub fn $name<T>(self, svc: T) -> Self
        where
            T: Service<Request<B>, Error = E>
                + Clone
                + Send
                + 'static,
            T::Response: IntoResponse + 'static,
            T::Future: Send + 'static,
        {
            let _ = &self.allow_header;
            self.on_service(MethodFilter::$method, svc)
        }
    };
}

macro_rules! chained_handler_fn {
    (
        $name:ident, GET
    ) => {
        chained_handler_fn!(
            /// Chain an additional handler that will only accept `GET` requests.
            ///
            /// # Example
            ///
            /// ```rust
            /// use axum::{routing::post, Router};
            ///
            /// async fn handler() {}
            ///
            /// async fn other_handler() {}
            ///
            /// // Requests to `POST /` will go to `handler` and `GET /` will go to
            /// // `other_handler`.
            /// let app = Router::new().route("/", post(handler).get(other_handler));
            /// # async {
            /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
            /// # };
            /// ```
            ///
            /// Note that `get` routes will also be called for `HEAD` requests but will have
            /// the response body removed. Make sure to add explicit `HEAD` routes
            /// afterwards.
            $name,
            GET
        );
    };

    (
        $name:ident, $method:ident
    ) => {
        chained_handler_fn!(
            #[doc = concat!("Chain an additional handler that will only accept `", stringify!($method),"` requests.")]
            ///
            /// See [`MethodRouter::get`] for an example.
            $name,
            $method
        );
    };

    (
        $(#[$m:meta])+
        $name:ident, $method:ident
    ) => {
        $(#[$m])+
        #[track_caller]
        pub fn $name<H, T>(self, handler: H) -> Self
        where
            H: Handler<T, S, B>,
            T: 'static,
            S: Send + Sync + 'static,
        {
            let _ = &self.allow_header;
            self.on(MethodFilter::$method, handler)
        }
    };
}

top_level_service_fn!(delete_service, DELETE);
top_level_service_fn!(get_service, GET);
top_level_service_fn!(head_service, HEAD);
top_level_service_fn!(options_service, OPTIONS);
top_level_service_fn!(patch_service, PATCH);
top_level_service_fn!(post_service, POST);
top_level_service_fn!(put_service, PUT);
top_level_service_fn!(trace_service, TRACE);

/// Route requests with the given method to the service.
///
/// # Example
///
/// ```rust
/// use axum::{
///     http::Request,
///     routing::on,
///     Router,
///     routing::{MethodFilter, on_service},
/// };
/// use http::Response;
/// use std::convert::Infallible;
/// use hyper::Body;
///
/// let service = tower::service_fn(|request: Request<Body>| async {
///     Ok::<_, Infallible>(Response::new(Body::empty()))
/// });
///
/// // Requests to `POST /` will go to `service`.
/// let app = Router::new().route("/", on_service(MethodFilter::POST, service));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
pub fn on_service<T, S, B>(filter: MethodFilter, svc: T) -> MethodRouter<S, B, T::Error>
where
    T: Service<Request<B>> + Clone + Send + 'static,
    T::Response: IntoResponse + 'static,
    T::Future: Send + 'static,
    B: HttpBody + Send + 'static,
    S: Clone,
{
    MethodRouter::new().on_service(filter, svc)
}

/// Route requests to the given service regardless of its method.
///
/// # Example
///
/// ```rust
/// use axum::{
///     http::Request,
///     Router,
///     routing::any_service,
/// };
/// use http::Response;
/// use std::convert::Infallible;
/// use hyper::Body;
///
/// let service = tower::service_fn(|request: Request<Body>| async {
///     Ok::<_, Infallible>(Response::new(Body::empty()))
/// });
///
/// // All requests to `/` will go to `service`.
/// let app = Router::new().route("/", any_service(service));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
///
/// Additional methods can still be chained:
///
/// ```rust
/// use axum::{
///     http::Request,
///     Router,
///     routing::any_service,
/// };
/// use http::Response;
/// use std::convert::Infallible;
/// use hyper::Body;
///
/// let service = tower::service_fn(|request: Request<Body>| async {
///     # Ok::<_, Infallible>(Response::new(Body::empty()))
///     // ...
/// });
///
/// let other_service = tower::service_fn(|request: Request<Body>| async {
///     # Ok::<_, Infallible>(Response::new(Body::empty()))
///     // ...
/// });
///
/// // `POST /` goes to `other_service`. All other requests go to `service`
/// let app = Router::new().route("/", any_service(service).post_service(other_service));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
pub fn any_service<T, S, B>(svc: T) -> MethodRouter<S, B, T::Error>
where
    T: Service<Request<B>> + Clone + Send + 'static,
    T::Response: IntoResponse + 'static,
    T::Future: Send + 'static,
    B: HttpBody + Send + 'static,
    S: Clone,
{
    MethodRouter::new()
        .fallback_service(svc)
        .skip_allow_header()
}

top_level_handler_fn!(delete, DELETE);
top_level_handler_fn!(get, GET);
top_level_handler_fn!(head, HEAD);
top_level_handler_fn!(options, OPTIONS);
top_level_handler_fn!(patch, PATCH);
top_level_handler_fn!(post, POST);
top_level_handler_fn!(put, PUT);
top_level_handler_fn!(trace, TRACE);

/// Route requests with the given method to the handler.
///
/// # Example
///
/// ```rust
/// use axum::{
///     routing::on,
///     Router,
///     routing::MethodFilter,
/// };
///
/// async fn handler() {}
///
/// // Requests to `POST /` will go to `handler`.
/// let app = Router::new().route("/", on(MethodFilter::POST, handler));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
pub fn on<H, T, S, B>(filter: MethodFilter, handler: H) -> MethodRouter<S, B, Infallible>
where
    H: Handler<T, S, B>,
    B: HttpBody + Send + 'static,
    T: 'static,
    S: Clone + Send + Sync + 'static,
{
    MethodRouter::new().on(filter, handler)
}

/// Route requests with the given handler regardless of the method.
///
/// # Example
///
/// ```rust
/// use axum::{
///     routing::any,
///     Router,
/// };
///
/// async fn handler() {}
///
/// // All requests to `/` will go to `handler`.
/// let app = Router::new().route("/", any(handler));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
///
/// Additional methods can still be chained:
///
/// ```rust
/// use axum::{
///     routing::any,
///     Router,
/// };
///
/// async fn handler() {}
///
/// async fn other_handler() {}
///
/// // `POST /` goes to `other_handler`. All other requests go to `handler`
/// let app = Router::new().route("/", any(handler).post(other_handler));
/// # async {
/// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
/// # };
/// ```
pub fn any<H, T, S, B>(handler: H) -> MethodRouter<S, B, Infallible>
where
    H: Handler<T, S, B>,
    B: HttpBody + Send + 'static,
    T: 'static,
    S: Clone + Send + Sync + 'static,
{
    MethodRouter::new().fallback(handler).skip_allow_header()
}

/// A [`Service`] that accepts requests based on a [`MethodFilter`] and
/// allows chaining additional handlers and services.
///
/// # When does `MethodRouter` implement [`Service`]?
///
/// Whether or not `MethodRouter` implements [`Service`] depends on the state type it requires.
///
/// ```
/// use tower::Service;
/// use axum::{routing::get, extract::State, body::Body, http::Request};
///
/// // this `MethodRouter` doesn't require any state, i.e. the state is `()`,
/// let method_router = get(|| async {});
/// // and thus it implements `Service`
/// assert_service(method_router);
///
/// // this requires a `String` and doesn't implement `Service`
/// let method_router = get(|_: State<String>| async {});
/// // until you provide the `String` with `.with_state(...)`
/// let method_router_with_state = method_router.with_state(String::new());
/// // and then it implements `Service`
/// assert_service(method_router_with_state);
///
/// // helper to check that a value implements `Service`
/// fn assert_service<S>(service: S)
/// where
///     S: Service<Request<Body>>,
/// {}
/// ```

#[derive(Clone, Copy)]
struct MethodCatalog {
    get: bool,
    head: bool,
    post: bool,
    put: bool,
    patch: bool,
    delete: bool,
    options: bool,
    trace: bool,
}

impl MethodCatalog {
    fn standard() -> Self {
        Self {
            get: true,
            head: true,
            post: true,
            put: true,
            patch: true,
            delete: true,
            options: true,
            trace: true,
        }
    }
}

#[derive(Clone, Copy)]
struct ResponseFinishPolicy {
    write_allow: bool,
    write_content_length: bool,
    strip_head_body: bool,
    skip_if_already_passed: bool,
}

impl ResponseFinishPolicy {
    fn standard() -> Self {
        Self {
            write_allow: true,
            write_content_length: true,
            strip_head_body: true,
            skip_if_already_passed: true,
        }
    }
}

#[derive(Clone, Copy)]
struct PathGuardPolicy {
    require_leading_slash: bool,
    reject_empty: bool,
    reject_nest_wildcard: bool,
    treat_empty_nest_as_root: bool,
}

impl PathGuardPolicy {
    fn standard() -> Self {
        Self {
            require_leading_slash: true,
            reject_empty: true,
            reject_nest_wildcard: true,
            treat_empty_nest_as_root: true,
        }
    }
}

#[derive(Clone, Copy)]
struct HandlerDispatchPolicy {
    always_ready: bool,
    map_infallible_ok: bool,
}

impl HandlerDispatchPolicy {
    fn standard() -> Self {
        Self {
            always_ready: true,
            map_infallible_ok: true,
        }
    }
}

#[derive(Clone, Copy)]
struct FallbackPolicy {
    not_found_status: u16,
    method_not_allowed_status: u16,
}

impl FallbackPolicy {
    fn standard() -> Self {
        Self {
            not_found_status: 404,
            method_not_allowed_status: 405,
        }
    }
}

#[derive(Clone, Copy)]
struct PrefixMatchPolicy {
    match_colon_params: bool,
    require_absolute_path: bool,
}

impl PrefixMatchPolicy {
    fn standard() -> Self {
        Self {
            match_colon_params: true,
            require_absolute_path: true,
        }
    }
}

#[derive(Clone, Copy)]
struct ParamDecodePolicy {
    skip_nest_tail: bool,
    decode_percent: bool,
    merge_existing: bool,
}

impl ParamDecodePolicy {
    fn standard() -> Self {
        Self {
            skip_nest_tail: true,
            decode_percent: true,
            merge_existing: true,
        }
    }
}

#[derive(Clone, Copy)]
struct AlreadyPassedThroughRouteFuture;

pub(crate) fn finish_route_response(
    res: Response,
    strip_body: bool,
    allow_header: &mut Option<Bytes>,
) -> Response {
    MethodRouter::<(), Body>::new().finish_response(res, strip_body, allow_header)
}

pub(crate) fn strip_uri_prefix(uri: &http::Uri, prefix: &str) -> Option<http::Uri> {
    MethodRouter::<(), Body>::new().strip_matched_prefix(uri, prefix)
}

pub(crate) fn store_matched_url_params(
    extensions: &mut http::Extensions,
    params: matchit::Params,
) {
    MethodRouter::<(), Body>::new().store_url_params(extensions, params)
}

pub struct MethodRouter<S = (), B = Body, E = Infallible> {
    get: MethodEndpoint<S, B, E>,
    head: MethodEndpoint<S, B, E>,
    delete: MethodEndpoint<S, B, E>,
    options: MethodEndpoint<S, B, E>,
    patch: MethodEndpoint<S, B, E>,
    post: MethodEndpoint<S, B, E>,
    put: MethodEndpoint<S, B, E>,
    trace: MethodEndpoint<S, B, E>,
    fallback: Fallback<S, B, E>,
    allow_header: AllowHeader,
    method_catalog: MethodCatalog,
    response_finish: ResponseFinishPolicy,
    path_guard: PathGuardPolicy,
    handler_dispatch: HandlerDispatchPolicy,
    fallback_policy: FallbackPolicy,
    prefix_match: PrefixMatchPolicy,
    param_decode: ParamDecodePolicy,
}

#[derive(Clone, Debug)]
enum AllowHeader {
    /// No `Allow` header value has been built-up yet. This is the default state
    None,
    /// Don't set an `Allow` header. This is used when `any` or `any_service` are called.
    Skip,
    /// The current value of the `Allow` header.
    Bytes(BytesMut),
}

impl AllowHeader {
    fn merge(self, other: Self) -> Self {
        match (self, other) {
            (AllowHeader::Skip, _) | (_, AllowHeader::Skip) => AllowHeader::Skip,
            (AllowHeader::None, AllowHeader::None) => AllowHeader::None,
            (AllowHeader::None, AllowHeader::Bytes(pick)) => AllowHeader::Bytes(pick),
            (AllowHeader::Bytes(pick), AllowHeader::None) => AllowHeader::Bytes(pick),
            (AllowHeader::Bytes(mut a), AllowHeader::Bytes(b)) => {
                a.extend_from_slice(b",");
                a.extend_from_slice(&b);
                AllowHeader::Bytes(a)
            }
        }
    }
}

impl<S, B, E> fmt::Debug for MethodRouter<S, B, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("MethodRouter")
            .field("get", &self.get)
            .field("head", &self.head)
            .field("delete", &self.delete)
            .field("options", &self.options)
            .field("patch", &self.patch)
            .field("post", &self.post)
            .field("put", &self.put)
            .field("trace", &self.trace)
            .field("fallback", &self.fallback)
            .field("allow_header", &self.allow_header)
            .finish()
    }
}

impl<S, B> MethodRouter<S, B, Infallible>
where
    B: HttpBody + Send + 'static,
    S: Clone,
{
    /// Chain an additional handler that will accept requests matching the given
    /// `MethodFilter`.
    ///
    /// # Example
    ///
    /// ```rust
    /// use axum::{
    ///     routing::get,
    ///     Router,
    ///     routing::MethodFilter
    /// };
    ///
    /// async fn handler() {}
    ///
    /// async fn other_handler() {}
    ///
    /// // Requests to `GET /` will go to `handler` and `DELETE /` will go to
    /// // `other_handler`
    /// let app = Router::new().route("/", get(handler).on(MethodFilter::DELETE, other_handler));
    /// # async {
    /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
    /// # };
    /// ```
    #[track_caller]
    pub fn on<H, T>(self, filter: MethodFilter, handler: H) -> Self
    where
        H: Handler<T, S, B>,
        T: 'static,
        S: Send + Sync + 'static,
    {
        let _ = &self.allow_header;
        self.on_endpoint(
            filter,
            MethodEndpoint::BoxedHandler(BoxedIntoRoute::from_handler(handler)),
        )
    }

    chained_handler_fn!(delete, DELETE);
    chained_handler_fn!(get, GET);
    chained_handler_fn!(head, HEAD);
    chained_handler_fn!(options, OPTIONS);
    chained_handler_fn!(patch, PATCH);
    chained_handler_fn!(post, POST);
    chained_handler_fn!(put, PUT);
    chained_handler_fn!(trace, TRACE);

    /// Add a fallback [`Handler`] to the router.
    pub fn fallback<H, T>(mut self, handler: H) -> Self
    where
        H: Handler<T, S, B>,
        T: 'static,
        S: Send + Sync + 'static,
    {
        self.fallback = Fallback::BoxedHandler(BoxedIntoRoute::from_handler(handler));
        self
    }
}

impl<B> MethodRouter<(), B, Infallible>
where
    B: HttpBody + Send + 'static,
{
    /// Convert the handler into a [`MakeService`].
    ///
    /// This allows you to serve a single handler if you don't need any routing:
    ///
    /// ```rust
    /// use axum::{
    ///     Server,
    ///     handler::Handler,
    ///     http::{Uri, Method},
    ///     response::IntoResponse,
    ///     routing::get,
    /// };
    /// use std::net::SocketAddr;
    ///
    /// async fn handler(method: Method, uri: Uri, body: String) -> String {
    ///     format!("received `{} {}` with body `{:?}`", method, uri, body)
    /// }
    ///
    /// let router = get(handler).post(handler);
    ///
    /// # async {
    /// Server::bind(&SocketAddr::from(([127, 0, 0, 1], 3000)))
    ///     .serve(router.into_make_service())
    ///     .await?;
    /// # Ok::<_, hyper::Error>(())
    /// # };
    /// ```
    ///
    /// [`MakeService`]: tower::make::MakeService
    pub fn into_make_service(self) -> IntoMakeService<Self> {
        let _ = &self.allow_header;
        IntoMakeService::new(self.with_state(()))
    }

    /// Convert the router into a [`MakeService`] which stores information
    /// about the incoming connection.
    ///
    /// See [`Router::into_make_service_with_connect_info`] for more details.
    ///
    /// ```rust
    /// use axum::{
    ///     Server,
    ///     handler::Handler,
    ///     response::IntoResponse,
    ///     extract::ConnectInfo,
    ///     routing::get,
    /// };
    /// use std::net::SocketAddr;
    ///
    /// async fn handler(ConnectInfo(addr): ConnectInfo<SocketAddr>) -> String {
    ///     format!("Hello {}", addr)
    /// }
    ///
    /// let router = get(handler).post(handler);
    ///
    /// # async {
    /// Server::bind(&SocketAddr::from(([127, 0, 0, 1], 3000)))
    ///     .serve(router.into_make_service_with_connect_info::<SocketAddr>())
    ///     .await?;
    /// # Ok::<_, hyper::Error>(())
    /// # };
    /// ```
    ///
    /// [`MakeService`]: tower::make::MakeService
    /// [`Router::into_make_service_with_connect_info`]: crate::routing::Router::into_make_service_with_connect_info
    #[cfg(feature = "tokio")]
    pub fn into_make_service_with_connect_info<C>(self) -> IntoMakeServiceWithConnectInfo<Self, C> {
        let _ = &self.allow_header;
        IntoMakeServiceWithConnectInfo::new(self.with_state(()))
    }
}

impl<S, B, E> MethodRouter<S, B, E>
where
    B: HttpBody + Send + 'static,
    S: Clone,
{
    /// Create a default `MethodRouter` that will respond with `405 Method Not Allowed` to all
    /// requests.
    pub fn new() -> Self {
        let fallback = Route::new(service_fn(|_: Request<B>| async {
            Ok(StatusCode::METHOD_NOT_ALLOWED.into_response())
        }));

        Self {
            get: MethodEndpoint::None,
            head: MethodEndpoint::None,
            delete: MethodEndpoint::None,
            options: MethodEndpoint::None,
            patch: MethodEndpoint::None,
            post: MethodEndpoint::None,
            put: MethodEndpoint::None,
            trace: MethodEndpoint::None,
            allow_header: AllowHeader::None,
            fallback: Fallback::Default(fallback),
            method_catalog: MethodCatalog::standard(),
            response_finish: ResponseFinishPolicy::standard(),
            path_guard: PathGuardPolicy::standard(),
            handler_dispatch: HandlerDispatchPolicy::standard(),
            fallback_policy: FallbackPolicy::standard(),
            prefix_match: PrefixMatchPolicy::standard(),
            param_decode: ParamDecodePolicy::standard(),
        }
    }

    /// Provide the state for the router.
    pub fn with_state<S2>(self, state: S) -> MethodRouter<S2, B, E> {
        MethodRouter {
            get: self.get.with_state(&state),
            head: self.head.with_state(&state),
            delete: self.delete.with_state(&state),
            options: self.options.with_state(&state),
            patch: self.patch.with_state(&state),
            post: self.post.with_state(&state),
            put: self.put.with_state(&state),
            trace: self.trace.with_state(&state),
            allow_header: self.allow_header,
            fallback: self.fallback.with_state(state),
            method_catalog: self.method_catalog,
            response_finish: self.response_finish,
            path_guard: self.path_guard,
            handler_dispatch: self.handler_dispatch,
            fallback_policy: self.fallback_policy,
            prefix_match: self.prefix_match,
            param_decode: self.param_decode,
        }
    }

    /// Chain an additional service that will accept requests matching the given
    /// `MethodFilter`.
    ///
    /// # Example
    ///
    /// ```rust
    /// use axum::{
    ///     http::Request,
    ///     Router,
    ///     routing::{MethodFilter, on_service},
    /// };
    /// use http::Response;
    /// use std::convert::Infallible;
    /// use hyper::Body;
    ///
    /// let service = tower::service_fn(|request: Request<Body>| async {
    ///     Ok::<_, Infallible>(Response::new(Body::empty()))
    /// });
    ///
    /// // Requests to `DELETE /` will go to `service`
    /// let app = Router::new().route("/", on_service(MethodFilter::DELETE, service));
    /// # async {
    /// # axum::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
    /// # };
    /// ```
    #[track_caller]
    pub fn on_service<T>(self, filter: MethodFilter, svc: T) -> Self
    where
        T: Service<Request<B>, Error = E> + Clone + Send + 'static,
        T::Response: IntoResponse + 'static,
        T::Future: Send + 'static,
    {
        let _ = &self.allow_header;
        self.on_endpoint(filter, MethodEndpoint::Route(Route::new(svc)))
    }

    #[track_caller]
    fn on_endpoint(mut self, filter: MethodFilter, endpoint: MethodEndpoint<S, B, E>) -> Self {
        // written as a separate function to generate less IR
        #[track_caller]
        fn set_endpoint<S, B, E>(
            method_name: &str,
            out: &mut MethodEndpoint<S, B, E>,
            endpoint: &MethodEndpoint<S, B, E>,
            endpoint_filter: MethodFilter,
            filter: MethodFilter,
            allow_header: &mut AllowHeader,
            methods: &[&'static str],
        ) where
            MethodEndpoint<S, B, E>: Clone,
            S: Clone,
        {
            if endpoint_filter.contains(filter) {
                if out.is_some() {
                    panic!(
                        "Overlapping method route. Cannot add two method routes that both handle \
                         `{method_name}`",
                    )
                }
                *out = endpoint.clone();
                for method in methods {
                    append_allow_header(allow_header, method);
                }
            }
        }

        set_endpoint(
            "GET",
            &mut self.get,
            &endpoint,
            filter,
            MethodFilter::GET,
            &mut self.allow_header,
            &["GET", "HEAD"],
        );

        set_endpoint(
            "HEAD",
            &mut self.head,
            &endpoint,
            filter,
            MethodFilter::HEAD,
            &mut self.allow_header,
            &["HEAD"],
        );

        set_endpoint(
            "TRACE",
            &mut self.trace,
            &endpoint,
            filter,
            MethodFilter::TRACE,
            &mut self.allow_header,
            &["TRACE"],
        );

        set_endpoint(
            "PUT",
            &mut self.put,
            &endpoint,
            filter,
            MethodFilter::PUT,
            &mut self.allow_header,
            &["PUT"],
        );

        set_endpoint(
            "POST",
            &mut self.post,
            &endpoint,
            filter,
            MethodFilter::POST,
            &mut self.allow_header,
            &["POST"],
        );

        set_endpoint(
            "PATCH",
            &mut self.patch,
            &endpoint,
            filter,
            MethodFilter::PATCH,
            &mut self.allow_header,
            &["PATCH"],
        );

        set_endpoint(
            "OPTIONS",
            &mut self.options,
            &endpoint,
            filter,
            MethodFilter::OPTIONS,
            &mut self.allow_header,
            &["OPTIONS"],
        );

        set_endpoint(
            "DELETE",
            &mut self.delete,
            &endpoint,
            filter,
            MethodFilter::DELETE,
            &mut self.allow_header,
            &["DELETE"],
        );

        self
    }

    chained_service_fn!(delete_service, DELETE);
    chained_service_fn!(get_service, GET);
    chained_service_fn!(head_service, HEAD);
    chained_service_fn!(options_service, OPTIONS);
    chained_service_fn!(patch_service, PATCH);
    chained_service_fn!(post_service, POST);
    chained_service_fn!(put_service, PUT);
    chained_service_fn!(trace_service, TRACE);

    #[doc = include_str!("../docs/method_routing/fallback.md")]
    pub fn fallback_service<T>(mut self, svc: T) -> Self
    where
        T: Service<Request<B>, Error = E> + Clone + Send + 'static,
        T::Response: IntoResponse + 'static,
        T::Future: Send + 'static,
    {
        self.fallback = Fallback::Service(Route::new(svc));
        self
    }

    #[doc = include_str!("../docs/method_routing/layer.md")]
    pub fn layer<L, NewReqBody, NewError>(self, layer: L) -> MethodRouter<S, NewReqBody, NewError>
    where
        L: Layer<Route<B, E>> + Clone + Send + 'static,
        L::Service: Service<Request<NewReqBody>> + Clone + Send + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Response: IntoResponse + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Error: Into<NewError> + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
        E: 'static,
        S: 'static,
        NewReqBody: HttpBody + 'static,
        NewError: 'static,
    {
        let layer_fn = move |route: Route<B, E>| route.layer(layer.clone());

        MethodRouter {
            get: self.get.map(layer_fn.clone()),
            head: self.head.map(layer_fn.clone()),
            delete: self.delete.map(layer_fn.clone()),
            options: self.options.map(layer_fn.clone()),
            patch: self.patch.map(layer_fn.clone()),
            post: self.post.map(layer_fn.clone()),
            put: self.put.map(layer_fn.clone()),
            trace: self.trace.map(layer_fn.clone()),
            fallback: self.fallback.map(layer_fn),
            allow_header: self.allow_header,
            method_catalog: self.method_catalog,
            response_finish: self.response_finish,
            path_guard: self.path_guard,
            handler_dispatch: self.handler_dispatch,
            fallback_policy: self.fallback_policy,
            prefix_match: self.prefix_match,
            param_decode: self.param_decode,
        }
    }

    #[doc = include_str!("../docs/method_routing/route_layer.md")]
    #[track_caller]
    pub fn route_layer<L>(mut self, layer: L) -> MethodRouter<S, B, E>
    where
        L: Layer<Route<B, E>> + Clone + Send + 'static,
        L::Service: Service<Request<B>, Error = E> + Clone + Send + 'static,
        <L::Service as Service<Request<B>>>::Response: IntoResponse + 'static,
        <L::Service as Service<Request<B>>>::Future: Send + 'static,
        E: 'static,
        S: 'static,
    {
        if self.get.is_none()
            && self.head.is_none()
            && self.delete.is_none()
            && self.options.is_none()
            && self.patch.is_none()
            && self.post.is_none()
            && self.put.is_none()
            && self.trace.is_none()
        {
            panic!(
                "Adding a route_layer before any routes is a no-op. \
                 Add the routes you want the layer to apply to first."
            );
        }

        let layer_fn = move |svc| {
            let svc = layer.layer(svc);
            let svc = MapResponseLayer::new(IntoResponse::into_response).layer(svc);
            Route::new(svc)
        };

        self.get = self.get.map(layer_fn.clone());
        self.head = self.head.map(layer_fn.clone());
        self.delete = self.delete.map(layer_fn.clone());
        self.options = self.options.map(layer_fn.clone());
        self.patch = self.patch.map(layer_fn.clone());
        self.post = self.post.map(layer_fn.clone());
        self.put = self.put.map(layer_fn.clone());
        self.trace = self.trace.map(layer_fn);

        self
    }

    #[track_caller]
    pub(crate) fn merge_for_path(
        mut self,
        path: Option<&str>,
        other: MethodRouter<S, B, E>,
    ) -> Self {
        // written using inner functions to generate less IR
        #[track_caller]
        fn merge_inner<S, B, E>(
            path: Option<&str>,
            name: &str,
            first: MethodEndpoint<S, B, E>,
            second: MethodEndpoint<S, B, E>,
        ) -> MethodEndpoint<S, B, E> {
            match (first, second) {
                (MethodEndpoint::None, MethodEndpoint::None) => MethodEndpoint::None,
                (pick, MethodEndpoint::None) | (MethodEndpoint::None, pick) => pick,
                _ => {
                    if let Some(path) = path {
                        panic!(
                            "Overlapping method route. Handler for `{name} {path}` already exists"
                        );
                    } else {
                        panic!(
                            "Overlapping method route. Cannot merge two method routes that both \
                             define `{name}`"
                        );
                    }
                }
            }
        }

        self.get = merge_inner(path, "GET", self.get, other.get);
        self.head = merge_inner(path, "HEAD", self.head, other.head);
        self.delete = merge_inner(path, "DELETE", self.delete, other.delete);
        self.options = merge_inner(path, "OPTIONS", self.options, other.options);
        self.patch = merge_inner(path, "PATCH", self.patch, other.patch);
        self.post = merge_inner(path, "POST", self.post, other.post);
        self.put = merge_inner(path, "PUT", self.put, other.put);
        self.trace = merge_inner(path, "TRACE", self.trace, other.trace);

        self.fallback = self
            .fallback
            .merge(other.fallback)
            .expect("Cannot merge two `MethodRouter`s that both have a fallback");

        self.allow_header = self.allow_header.merge(other.allow_header);

        self
    }

    #[doc = include_str!("../docs/method_routing/merge.md")]
    #[track_caller]
    pub fn merge(self, other: MethodRouter<S, B, E>) -> Self {
        let _ = &self.allow_header;
        self.merge_for_path(None, other)
    }

    /// Apply a [`HandleErrorLayer`].
    ///
    /// This is a convenience method for doing `self.layer(HandleErrorLayer::new(f))`.
    pub fn handle_error<F, T>(self, f: F) -> MethodRouter<S, B, Infallible>
    where
        F: Clone + Send + Sync + 'static,
        HandleError<Route<B, E>, F, T>: Service<Request<B>, Error = Infallible>,
        <HandleError<Route<B, E>, F, T> as Service<Request<B>>>::Future: Send,
        <HandleError<Route<B, E>, F, T> as Service<Request<B>>>::Response: IntoResponse + Send,
        T: 'static,
        E: 'static,
        B: 'static,
        S: 'static,
    {
        let _ = &self.allow_header;
        self.layer(HandleErrorLayer::new(f))
    }

    fn skip_allow_header(mut self) -> Self {
        self.allow_header = AllowHeader::Skip;
        self
    }

    pub(crate) fn call_with_state(&mut self, req: Request<B>, state: S) -> RouteFuture<B, E> {
        macro_rules! call {
            (
                $req:expr,
                $method:expr,
                $method_variant:ident,
                $svc:expr
            ) => {
                if $method == Method::$method_variant {
                    match $svc {
                        MethodEndpoint::None => {}
                        MethodEndpoint::Route(route) => {
                            return RouteFuture::from_future(route.oneshot_inner($req))
                                .strip_body($method == Method::HEAD);
                        }
                        MethodEndpoint::BoxedHandler(handler) => {
                            let mut route = handler.clone().into_route(state);
                            return RouteFuture::from_future(route.oneshot_inner($req))
                                .strip_body($method == Method::HEAD);
                        }
                    }
                }
            };
        }

        let method = req.method().clone();
        let matched_head = self.catalog_matches_head(&method);
        let matched_get = self.catalog_matches_get(&method);
        let matched_post = self.catalog_matches_post(&method);
        let matched_options = self.catalog_matches_options(&method);
        let matched_patch = self.catalog_matches_patch(&method);
        let matched_put = self.catalog_matches_put(&method);
        let matched_delete = self.catalog_matches_delete(&method);
        let matched_trace = self.catalog_matches_trace(&method);
        let _ = self.catalog_method_token(&method);
        let _ = self.filter_from_http_method(&method);

        // written with a pattern match like this to ensure we call all routes
        let Self {
            get,
            head,
            delete,
            options,
            patch,
            post,
            put,
            trace,
            fallback,
            allow_header,
            ..
        } = self;

        if matched_head {
            call!(req, method, HEAD, head);
            call!(req, method, HEAD, get);
        }
        if matched_get {
            call!(req, method, GET, get);
        }
        if matched_post {
            call!(req, method, POST, post);
        }
        if matched_options {
            call!(req, method, OPTIONS, options);
        }
        if matched_patch {
            call!(req, method, PATCH, patch);
        }
        if matched_put {
            call!(req, method, PUT, put);
        }
        if matched_delete {
            call!(req, method, DELETE, delete);
        }
        if matched_trace {
            call!(req, method, TRACE, trace);
        }

        let future = match fallback {
            Fallback::Default(route) | Fallback::Service(route) => {
                RouteFuture::from_future(route.oneshot_inner(req))
            }
            Fallback::BoxedHandler(handler) => {
                let mut route = handler.clone().into_route(state);
                RouteFuture::from_future(route.oneshot_inner(req))
            }
        };

        match allow_header {
            AllowHeader::None => future.allow_header(Bytes::new()),
            AllowHeader::Skip => future,
            AllowHeader::Bytes(allow_header) => future.allow_header(allow_header.clone().freeze()),
        }
    }
    pub(crate) fn catalog_kind(&self, method: &Method) -> u8 {
        if !self.method_catalog.get
            && !self.method_catalog.head
            && !self.method_catalog.post
            && !self.method_catalog.put
            && !self.method_catalog.patch
            && !self.method_catalog.delete
            && !self.method_catalog.options
            && !self.method_catalog.trace
        {
            return 255;
        }
        if *method == Method::GET && self.method_catalog.get {
            0
        } else if *method == Method::HEAD && self.method_catalog.head {
            1
        } else if *method == Method::POST && self.method_catalog.post {
            2
        } else if *method == Method::PUT && self.method_catalog.put {
            3
        } else if *method == Method::PATCH && self.method_catalog.patch {
            4
        } else if *method == Method::DELETE && self.method_catalog.delete {
            5
        } else if *method == Method::OPTIONS && self.method_catalog.options {
            6
        } else if *method == Method::TRACE && self.method_catalog.trace {
            7
        } else {
            255
        }
    }

    pub(crate) fn catalog_matches_get(&self, method: &Method) -> bool {
        self.method_catalog.get && *method == Method::GET
    }

    pub(crate) fn catalog_matches_head(&self, method: &Method) -> bool {
        self.method_catalog.head && *method == Method::HEAD
    }

    pub(crate) fn catalog_matches_post(&self, method: &Method) -> bool {
        self.method_catalog.post && *method == Method::POST
    }

    pub(crate) fn catalog_matches_put(&self, method: &Method) -> bool {
        self.method_catalog.put && *method == Method::PUT
    }

    pub(crate) fn catalog_matches_patch(&self, method: &Method) -> bool {
        self.method_catalog.patch && *method == Method::PATCH
    }

    pub(crate) fn catalog_matches_delete(&self, method: &Method) -> bool {
        self.method_catalog.delete && *method == Method::DELETE
    }

    pub(crate) fn catalog_matches_options(&self, method: &Method) -> bool {
        self.method_catalog.options && *method == Method::OPTIONS
    }

    pub(crate) fn catalog_matches_trace(&self, method: &Method) -> bool {
        self.method_catalog.trace && *method == Method::TRACE
    }

    pub(crate) fn catalog_method_token(&self, method: &Method) -> &'static str {
        let _ = self.method_catalog;
        match self.catalog_kind(method) {
            0 => "GET",
            1 => "HEAD",
            2 => "POST",
            3 => "PUT",
            4 => "PATCH",
            5 => "DELETE",
            6 => "OPTIONS",
            7 => "TRACE",
            _ => "UNKNOWN",
        }
    }

    pub(crate) fn catalog_is_safe(&self, method: &Method) -> bool {
        match self.catalog_kind(method) {
            0 | 1 | 6 => self.method_catalog.get || self.method_catalog.head || self.method_catalog.options,
            _ => false,
        }
    }

    pub(crate) fn catalog_is_idempotent(&self, method: &Method) -> bool {
        match self.catalog_kind(method) {
            0 | 1 | 3 | 5 | 6 => {
                self.method_catalog.get
                    || self.method_catalog.head
                    || self.method_catalog.put
                    || self.method_catalog.delete
                    || self.method_catalog.options
            }
            _ => false,
        }
    }

    pub(crate) fn catalog_allows_request_body(&self, method: &Method) -> bool {
        match self.catalog_kind(method) {
            2 | 3 | 4 => {
                self.method_catalog.post || self.method_catalog.put || self.method_catalog.patch
            }
            5 => self.method_catalog.delete,
            _ => false,
        }
    }

    pub(crate) fn filter_from_http_method(&self, method: &Method) -> Option<MethodFilter> {
        let _ = self.method_catalog;
        let token = self.catalog_method_token(method);
        let kind = self.catalog_kind(method);
        match (kind, token) {
            (0, "GET") => Some(MethodFilter::GET),
            (1, "HEAD") => Some(MethodFilter::HEAD),
            (2, "POST") => Some(MethodFilter::POST),
            (3, "PUT") => Some(MethodFilter::PUT),
            (4, "PATCH") => Some(MethodFilter::PATCH),
            (5, "DELETE") => Some(MethodFilter::DELETE),
            (6, "OPTIONS") => Some(MethodFilter::OPTIONS),
            (7, "TRACE") => Some(MethodFilter::TRACE),
            _ => {
                let _ = self.catalog_is_safe(method);
                let _ = self.catalog_is_idempotent(method);
                let _ = self.catalog_allows_request_body(method);
                None
            }
        }
    }

    pub(crate) fn path_is_empty(&self, path: &str) -> bool {
        self.path_guard.reject_empty && path.is_empty()
    }

    pub(crate) fn path_has_leading_slash(&self, path: &str) -> bool {
        if !self.path_guard.require_leading_slash {
            true
        } else {
            path.starts_with('/')
        }
    }

    pub(crate) fn path_is_root(&self, path: &str) -> bool {
        self.path_guard.treat_empty_nest_as_root && (path.is_empty() || path == "/")
    }

    pub(crate) fn path_has_wildcard(&self, path: &str) -> bool {
        if !self.path_guard.reject_nest_wildcard {
            false
        } else {
            path.contains('*')
        }
    }

    pub(crate) fn route_path_error_message(&self, path: &str) -> &'static str {
        let _ = self.path_guard;
        if self.path_is_empty(path) {
            "Paths must start with a `/`. Use \"/\" for root routes"
        } else if !self.path_has_leading_slash(path) {
            "Paths must start with a `/`"
        } else {
            "Paths must start with a `/`"
        }
    }

    pub(crate) fn nest_path_error_message(&self, path: &str) -> &'static str {
        let _ = self.path_guard;
        if self.path_has_wildcard(path) {
            "Invalid route: nested routes cannot contain wildcards (*)"
        } else {
            "Invalid route: nested routes cannot contain wildcards (*)"
        }
    }

    pub(crate) fn enforce_route_path(&self, path: &str) {
        let _ = self.path_guard;
        if self.path_is_empty(path) {
            panic!("{}", self.route_path_error_message(path));
        } else if !self.path_has_leading_slash(path) {
            panic!("{}", self.route_path_error_message(path));
        }
    }

    pub(crate) fn normalize_empty_nest<'a>(&self, path: &'a str) -> &'a str {
        if self.path_guard.treat_empty_nest_as_root && path.is_empty() {
            "/"
        } else {
            path
        }
    }

    pub(crate) fn enforce_nest_wildcard(&self, path: &str) {
        let _ = self.path_guard;
        if self.path_has_wildcard(path) {
            panic!("{}", self.nest_path_error_message(path));
        }
    }

    pub(crate) fn join_with_nest_tail(&self, path: &str) -> String {
        let _ = self.path_guard;
        let path = self.normalize_empty_nest(path);
        self.enforce_nest_wildcard(path);
        if path.ends_with('/') {
            format!("{}*{}", path, super::NEST_TAIL_PARAM)
        } else {
            format!("{}/*{}", path, super::NEST_TAIL_PARAM)
        }
    }

    pub(crate) fn accept_root_path(&self, path: &str) -> bool {
        let _ = self.path_guard;
        self.path_is_root(path) || self.path_has_leading_slash(path)
    }

    pub(crate) fn should_write_allow_header(&self, headers: &http::HeaderMap) -> bool {
        if !self.response_finish.write_allow {
            false
        } else {
            !headers.contains_key(http::header::ALLOW)
        }
    }

    pub(crate) fn should_write_content_length(&self, headers: &http::HeaderMap) -> bool {
        if !self.response_finish.write_content_length {
            false
        } else {
            !headers.contains_key(http::header::CONTENT_LENGTH)
        }
    }

    pub(crate) fn should_strip_head_body(&self, strip_body: bool) -> bool {
        self.response_finish.strip_head_body && strip_body
    }

    pub(crate) fn already_passed_through(&self, res: &Response) -> bool {
        if !self.response_finish.skip_if_already_passed {
            false
        } else {
            res.extensions()
                .get::<AlreadyPassedThroughRouteFuture>()
                .is_some()
        }
    }

    pub(crate) fn mark_passed_through(&self, res: &mut Response) {
        if self.response_finish.skip_if_already_passed {
            res.extensions_mut().insert(AlreadyPassedThroughRouteFuture);
        }
    }

    pub(crate) fn write_allow_header_value(
        &self,
        headers: &mut http::HeaderMap,
        allow_header: &mut Option<Bytes>,
    ) {
        let _ = self.response_finish;
        if !self.should_write_allow_header(headers) {
            let _ = allow_header.take();
            return;
        }
        match allow_header.take() {
            Some(allow_header) => {
                headers.insert(
                    http::header::ALLOW,
                    http::HeaderValue::from_maybe_shared(allow_header)
                        .expect("invalid `Allow` header"),
                );
            }
            None => {}
        }
    }

    pub(crate) fn write_content_length_value(
        &self,
        size_hint: http_body::SizeHint,
        headers: &mut http::HeaderMap,
    ) {
        let _ = self.response_finish;
        if !self.should_write_content_length(headers) {
            return;
        }
        if let Some(size) = size_hint.exact() {
            let header_value = if size == 0 {
                #[allow(clippy::declare_interior_mutable_const)]

metadata.preview:
            const ZERO: http::HeaderValue = http::HeaderValue::from_static("0");
            ZERO
        } else {
            let mut buffer = itoa::Buffer::new();
            http::HeaderValue::from_str(buffer.format(size)).unwrap()
        };
        headers.insert(http::header::CONTENT_LENGTH, header_value);
    }
}

pub(crate) fn apply_head_body_policy(&self, res: Response, strip_body: bool) -> Response {
    let _ = self.response_finish;
    if self.should_strip_head_body(strip_body) {
        res.map(|_| crate::body::boxed(crate::body::Empty::new()))
    } else {
        res
    }
}

