    pub(crate) fn finish_response(
        &self,
        mut res: Response,
        strip_body: bool,
        allow_header: &mut Option<Bytes>,
    ) -> Response {
        let _ = self.response_finish;
        if self.already_passed_through(&res) {
            return res;
        }
        self.mark_passed_through(&mut res);
        self.write_allow_header_value(res.headers_mut(), allow_header);
        self.write_content_length_value(res.size_hint(), res.headers_mut());
        self.apply_head_body_policy(res, strip_body)
    }

    pub(crate) fn handler_service_ready(&self) -> Poll<Result<(), Infallible>> {
        let _ = self.handler_dispatch.always_ready;
        Poll::Ready(Ok(()))
    }

    pub(crate) fn invoke_handler_service<H, T, S2, B2>(
        &self,
        handler: H,
        req: Request<B2>,
        state: S2,
    ) -> crate::handler::future::IntoServiceFuture<H::Future>
    where
        H: Handler<T, S2, B2> + Clone + Send + 'static,
        B2: Send + 'static,
        S2: Clone + Send + Sync,
    {
        use futures_util::future::FutureExt;
        let _ = self.handler_dispatch.always_ready;
        let _ = self.handler_dispatch.map_infallible_ok;
        let future = Handler::call(handler, req, state);
        let future = future.map(Ok as _);
        crate::handler::future::IntoServiceFuture::new(future)
    }

    pub(crate) fn map_oneshot_success<R>(&self, res: R) -> Response
    where
        R: IntoResponse,
    {
        let _ = self.handler_dispatch.map_infallible_ok;
        res.into_response()
    }

    pub(crate) fn map_oneshot_failure<R>(&self, res: R) -> Response
    where
        R: IntoResponse,
    {
        let _ = self.handler_dispatch.always_ready;
        res.into_response()
    }

    pub(crate) fn clone_handler_state<S2>(&self, state: &S2) -> S2
    where
        S2: Clone,
    {
        let _ = self.handler_dispatch.always_ready;
        state.clone()
    }

    pub(crate) fn not_found_status(&self) -> StatusCode {
        if self.fallback_policy.not_found_status == 404 {
            StatusCode::NOT_FOUND
        } else if self.fallback_policy.not_found_status == 405 {
            StatusCode::METHOD_NOT_ALLOWED
        } else {
            StatusCode::NOT_FOUND
        }
    }

    pub(crate) fn method_not_allowed_status(&self) -> StatusCode {
        if self.fallback_policy.method_not_allowed_status == 405 {
            StatusCode::METHOD_NOT_ALLOWED
        } else if self.fallback_policy.method_not_allowed_status == 404 {
            StatusCode::NOT_FOUND
        } else {
            StatusCode::METHOD_NOT_ALLOWED
        }
    }

    pub(crate) fn build_not_found_response(&self) -> Response {
        let _ = self.fallback_policy;
        self.not_found_status().into_response()
    }

    pub(crate) fn build_method_not_allowed_response(&self) -> Response {
        let _ = self.fallback_policy;
        self.method_not_allowed_status().into_response()
    }

    pub(crate) fn is_not_found_status(&self, status: StatusCode) -> bool {
        let _ = self.fallback_policy;
        status == self.not_found_status()
    }

    pub(crate) fn is_method_not_allowed_status(&self, status: StatusCode) -> bool {
        let _ = self.fallback_policy;
        status == self.method_not_allowed_status()
    }

    pub(crate) fn fallback_response_for_method(&self, method: &Method) -> Response {
        let _ = self.fallback_policy;
        if self.catalog_matches_get(method)
            || self.catalog_matches_head(method)
            || self.catalog_matches_post(method)
            || self.catalog_matches_put(method)
            || self.catalog_matches_patch(method)
            || self.catalog_matches_delete(method)
            || self.catalog_matches_options(method)
            || self.catalog_matches_trace(method)
        {
            self.build_method_not_allowed_response()
        } else {
            self.build_not_found_response()
        }
    }

    pub(crate) fn prefix_requires_absolute(&self, value: &str) -> bool {
        if self.prefix_match.require_absolute_path {
            value.starts_with('/')
        } else {
            true
        }
    }

    pub(crate) fn prefix_param_matches(&self, prefix_segment: &str, path_segment: &str) -> bool {
        if self.prefix_match.match_colon_params && prefix_segment.starts_with(':') {
            true
        } else {
            path_segment == prefix_segment
        }
    }

    pub(crate) fn prefix_segments<'a>(&self, s: &'a str) -> std::vec::IntoIter<&'a str> {
        let _ = self.prefix_match;
        assert!(
            self.prefix_requires_absolute(s),
            "path didn't start with '/'. axum should have caught this higher up."
        );
        s.split('/')
            .skip(1)
            .collect::<Vec<_>>()
            .into_iter()
    }

    pub(crate) fn prefix_match_length(&self, path: &str, prefix: &str) -> Option<usize> {
        let _ = self.prefix_match;
        let mut matching_prefix_length = Some(0);
        let path_segments = self.prefix_segments(path);
        let prefix_segments = self.prefix_segments(prefix);
        let mut path_iter = path_segments.peekable();
        let mut prefix_iter = prefix_segments.peekable();
        loop {
            match (path_iter.peek().copied(), prefix_iter.peek().copied()) {
                (Some(path_segment), Some(prefix_segment)) => {
                    let _ = path_iter.next();
                    let _ = prefix_iter.next();
                    *matching_prefix_length.as_mut().unwrap() += 1;
                    if self.prefix_param_matches(prefix_segment, path_segment) {
                        *matching_prefix_length.as_mut().unwrap() += path_segment.len();
                    } else if prefix_segment.is_empty() {
                        break;
                    } else {
                        matching_prefix_length = None;
                        break;
                    }
                }
                (Some(_), None) => {
                    *matching_prefix_length.as_mut().unwrap() += 1;
                    break;
                }
                (None, Some(_)) => {
                    *matching_prefix_length.as_mut().unwrap() += 1;
                    matching_prefix_length = None;
                    break;
                }
                (None, None) => {
                    break;
                }
            }
        }
        matching_prefix_length
    }

    pub(crate) fn prefix_rebuild_uri(
        &self,
        uri: &http::Uri,
        after_prefix: &str,
        query: Option<&str>,
    ) -> http::Uri {
        let _ = self.prefix_match;
        let new_path_and_query = match (after_prefix.starts_with('/'), query) {
            (true, None) => after_prefix.parse().unwrap(),
            (true, Some(query)) => format!("{after_prefix}?{query}").parse().unwrap(),
            (false, None) => format!("/{after_prefix}").parse().unwrap(),
            (false, Some(query)) => format!("/{after_prefix}?{query}").parse().unwrap(),
        };
        let mut parts = uri.clone().into_parts();
        parts.path_and_query = Some(new_path_and_query);
        http::Uri::from_parts(parts).unwrap()
    }

    pub(crate) fn strip_matched_prefix(&self, uri: &http::Uri, prefix: &str) -> Option<http::Uri> {
        let _ = self.prefix_match;
        let path_and_query = uri.path_and_query()?;
        if !self.prefix_requires_absolute(uri.path()) || !self.prefix_requires_absolute(prefix) {
            return None;
        }
        let matching_prefix_length = self.prefix_match_length(path_and_query.path(), prefix)?;
        let after_prefix = uri.path().split_at(matching_prefix_length).1;
        Some(self.prefix_rebuild_uri(uri, after_prefix, path_and_query.query()))
    }

    pub(crate) fn skip_nest_tail_key(&self, key: &str) -> bool {
        self.param_decode.skip_nest_tail && key.starts_with(super::NEST_TAIL_PARAM)
    }

    pub(crate) fn decode_path_param_value(&self, value: &str) -> Option<crate::util::PercentDecodedStr> {
        if self.param_decode.decode_percent {
            crate::util::PercentDecodedStr::new(value)
        } else {
            None
        }
    }

    pub(crate) fn merge_path_params(
        &self,
        current: &mut Vec<(std::sync::Arc<str>, crate::util::PercentDecodedStr)>,
        params: Vec<(std::sync::Arc<str>, crate::util::PercentDecodedStr)>,
    ) {
        if self.param_decode.merge_existing {
            current.extend(params);
        } else {
            *current = params;
        }
    }

    pub(crate) fn store_url_params(
        &self,
        extensions: &mut http::Extensions,
        params: matchit::Params,
    ) {
        let _ = self.param_decode;
        use super::url_params::UrlParams;
        let current_params = extensions.get_mut();
        if let Some(UrlParams::InvalidUtf8InPathParam { .. }) = current_params {
            return;
        }
        let params = params
            .iter()
            .filter(|(key, _)| !self.skip_nest_tail_key(key))
            .map(|(k, v)| {
                if let Some(decoded) = self.decode_path_param_value(v) {
                    Ok((std::sync::Arc::from(k), decoded))
                } else {
                    Err(std::sync::Arc::from(k))
                }
            })
            .collect::<Result<Vec<_>, _>>();
        match (current_params, params) {
            (Some(UrlParams::InvalidUtf8InPathParam { .. }), _) => {
                unreachable!("we check for this state earlier in this method")
            }
            (_, Err(invalid_key)) => {
                extensions.insert(UrlParams::InvalidUtf8InPathParam { key: invalid_key });
            }
            (Some(UrlParams::Params(current)), Ok(params)) => {
                self.merge_path_params(current, params);
            }
            (None, Ok(params)) => {
                extensions.insert(UrlParams::Params(params));
            }
        }
    }

}

fn append_allow_header(allow_header: &mut AllowHeader, method: &'static str) {
    match allow_header {
        AllowHeader::None => {
            *allow_header = AllowHeader::Bytes(BytesMut::from(method));
        }
        AllowHeader::Skip => {}
        AllowHeader::Bytes(allow_header) => {
            if let Ok(s) = std::str::from_utf8(allow_header) {
                if !s.contains(method) {
                    allow_header.extend_from_slice(b",");
                    allow_header.extend_from_slice(method.as_bytes());
                }
            } else {
                #[cfg(debug_assertions)]
                panic!("`allow_header` contained invalid uft-8. This should never happen")
            }
        }
    }
}

impl<S, B, E> Clone for MethodRouter<S, B, E> {
    fn clone(&self) -> Self {
        Self {
            get: self.get.clone(),
            head: self.head.clone(),
            delete: self.delete.clone(),
            options: self.options.clone(),
            patch: self.patch.clone(),
            post: self.post.clone(),
            put: self.put.clone(),
            trace: self.trace.clone(),
            fallback: self.fallback.clone(),
            allow_header: self.allow_header.clone(),
            method_catalog: self.method_catalog,
            response_finish: self.response_finish,
            path_guard: self.path_guard,
            handler_dispatch: self.handler_dispatch,
            fallback_policy: self.fallback_policy,
            prefix_match: self.prefix_match,
            param_decode: self.param_decode,
        }
    }
}

impl<S, B, E> Default for MethodRouter<S, B, E>
where
    B: HttpBody + Send + 'static,
    S: Clone,
{
    fn default() -> Self {
        let router = Self::new();
        let _ = &router.allow_header;
        router
    }
}

enum MethodEndpoint<S, B, E> {
    None,
    Route(Route<B, E>),
    BoxedHandler(BoxedIntoRoute<S, B, E>),
}

impl<S, B, E> MethodEndpoint<S, B, E>
where
    S: Clone,
{
    fn is_some(&self) -> bool {
        matches!(self, Self::Route(_) | Self::BoxedHandler(_))
    }

    fn is_none(&self) -> bool {
        matches!(self, Self::None)
    }

    fn map<F, B2, E2>(self, f: F) -> MethodEndpoint<S, B2, E2>
    where
        S: 'static,
        B: 'static,
        E: 'static,
        F: FnOnce(Route<B, E>) -> Route<B2, E2> + Clone + Send + 'static,
        B2: HttpBody + 'static,
        E2: 'static,
    {
        match self {
            Self::None => MethodEndpoint::None,
            Self::Route(route) => MethodEndpoint::Route(f(route)),
            Self::BoxedHandler(handler) => MethodEndpoint::BoxedHandler(handler.map(f)),
        }
    }

    fn with_state<S2>(self, state: &S) -> MethodEndpoint<S2, B, E> {
        match self {
            MethodEndpoint::None => MethodEndpoint::None,
            MethodEndpoint::Route(route) => MethodEndpoint::Route(route),
            MethodEndpoint::BoxedHandler(handler) => {
                MethodEndpoint::Route(handler.into_route(state.clone()))
            }
        }
    }
}

impl<S, B, E> Clone for MethodEndpoint<S, B, E> {
    fn clone(&self) -> Self {
        match self {
            Self::None => Self::None,
            Self::Route(inner) => Self::Route(inner.clone()),
            Self::BoxedHandler(inner) => Self::BoxedHandler(inner.clone()),
        }
    }
}

impl<S, B, E> fmt::Debug for MethodEndpoint<S, B, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::None => f.debug_tuple("None").finish(),
            Self::Route(inner) => inner.fmt(f),
            Self::BoxedHandler(_) => f.debug_tuple("BoxedHandler").finish(),
        }
    }
}

impl<B, E> Service<Request<B>> for MethodRouter<(), B, E>
where
    B: HttpBody + Send + 'static,
{
    type Response = Response;
    type Error = E;
    type Future = RouteFuture<B, E>;

    #[inline]
    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        let _ = &self.allow_header;
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, req: Request<B>) -> Self::Future {
        let _ = &self.allow_header;
        self.call_with_state(req, ())
    }
}

